initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{context_source_registration_id}'
        method set to 'PATCH'
        Update Context Source Registration with CSR Id set to '${context_source_registration_id}' and subscription update fragment set to '${update_fragment}'
}
